276	impl Command for InitCommand {
277	    fn execute(&self, ui: &mut dyn UserInterface) -> Result<CommandResult> {
278	        // Check if config already exists
279	        if self.config_exists() && !self.args.force {
280	            ui.warning("Configuration already exists. Use --force to overwrite.");
281	            return Ok(CommandResult::failure(1));
282	        }
283	
284	        // Show init header with version
285	        let version = crate::updates::version::VERSION;
286	        ui.message(&format!(
287	            "\n{} {} {}\n",
288	            console::style("⛺").bold().magenta(),
289	            console::style(format!("bivvy v{}", version)).dim(),
290	            console::style("· init").dim(),
291	        ));
292	
293	        // Handle --from: copy config from another project
294	        if let Some(ref from_path) = self.args.from {
295	            return self.execute_from(ui, from_path);
296	        }
297	
298	        // Handle --template: use a specific template instead of detection
299	        if let Some(ref template_name) = self.args.template {
300	            return self.execute_template(ui, template_name);
301	        }
302	
303	        // Run detection
304	        let detection = DetectionRunner::run(&self.project_root);
305	
306	        // Show detected technologies
307	        if !detection.project.details.is_empty() {
308	            ui.message("Detected technologies:");
309	            for detail in &detection.project.details {
310	                ui.success(&format!("{} - {}", detail.name, detail.details.join(", ")));
311	            }
312	            ui.message("");
313	        }
314	
315	        // Show conflicts
316	        for conflict in &detection.conflicts {
317	            ui.warning(&conflict.message);
318	            ui.message(&format!("  Suggestion: {}", conflict.suggestion));
319	            ui.message("");
320	        }
321	
322	        // Collect steps to include
323	        let mut steps = Vec::new();
324	
325	        if self.args.minimal || !ui.is_interactive() {
326	            // Just use detected templates
327	            for suggestion in &detection.suggested_templates {
328	                steps.push(suggestion.name.to_string());
329	            }
330	        } else if !detection.suggested_templates.is_empty() {
331	            // Interactive multi-select checklist
332	            let options: Vec<PromptOption> = detection
333	                .suggested_templates
334	                .iter()
335	                .map(|s| PromptOption {
336	                    label: format!("{} — {}", s.name, s.reason),
337	                    value: s.name.to_string(),
338	                })
339	                .collect();
340	
341	            let all_values = detection
342	                .suggested_templates
343	                .iter()
344	                .map(|s| s.name.as_str())
345	                .collect::<Vec<_>>()
346	                .join(",");
347	
348	            let prompt = Prompt {
349	                key: "init_steps".to_string(),
350	                question: "Select steps to include".to_string(),
351	                prompt_type: PromptType::MultiSelect { options },
352	                default: Some(all_values),
353	            };
354	
355	            if let Ok(PromptResult::Strings(selected)) = ui.prompt(&prompt) {
356	                steps = selected;
357	            }
358	        }
359	
360	        // Load templates to enrich config output
361	        let loader = BuiltinLoader::new().ok();
362	        let steps_with_templates: Vec<(&str, Option<&Template>)> = steps
363	            .iter()
364	            .map(|name| {
365	                let template = loader.as_ref().and_then(|l| l.get(name));
366	                (name.as_str(), template)
367	            })
368	            .collect();
369	
370	        // Generate config
371	        let schema = Self::schema_path();
372	        let config = self.create_config(&steps_with_templates, schema.as_deref());
373	
374	        // Write config
375	        let bivvy_dir = self.project_root.join(".bivvy");
376	        fs::create_dir_all(&bivvy_dir)?;
377	        fs::write(bivvy_dir.join("config.yml"), &config)?;
378	
379	        // Update gitignore
380	        self.update_gitignore(ui)?;
381	
382	        ui.message("");
383	        ui.success("Created .bivvy/config.yml");
384	
385	        // Show init summary
386	        let step_names: Vec<&str> = steps.iter().map(|s| s.as_str()).collect();
387	        ui.message("Workflow: default");
388	        ui.message(&format!(
389	            "Steps: {} ({})",
390	            steps.len(),
391	            step_names.join(", ")
392	        ));
393	        ui.message("");
394	
395	        // Offer to run setup immediately (interactive only)
396	        if ui.is_interactive() {
397	            let prompt = Prompt {
398	                key: "run_after_init".to_string(),
399	                question: "Run setup now?".to_string(),
400	                prompt_type: PromptType::Select {
401	                    options: vec![
402	                        PromptOption {
403	                            label: "No  (n)".to_string(),
404	                            value: "no".to_string(),
405	                        },
406	                        PromptOption {
407	                            label: "Yes (y)".to_string(),
408	                            value: "yes".to_string(),
409	                        },
410	                    ],
411	                },
412	                default: Some("no".to_string()),
413	            };
414	
415	            if let Ok(PromptResult::String(answer)) = ui.prompt(&prompt) {
416	                if answer == "yes" {
417	                    ui.message("");
418	                    let run_args = RunArgs {
419	                        force: steps.iter().map(|s| s.to_string()).collect(),
420	                        suppress_header: true,
421	                        ..RunArgs::default()
422	                    };
423	                    let run_cmd = RunCommand::new(&self.project_root, run_args);
424	                    return run_cmd.execute(ui);
425	                }
426	            }
427	        }
428	
429	        ui.show_hint(hints::after_init());
430	
431	        Ok(CommandResult::success())
432	    }
433	}
