    #[test]
    fn init_with_force_overwrites() {
        let temp = TempDir::new().unwrap();
        let bivvy_dir = temp.path().join(".bivvy");
        fs::create_dir_all(&bivvy_dir).unwrap();
        fs::write(bivvy_dir.join("config.yml"), "app_name: old").unwrap();

        let args = InitArgs {
            force: true,
            minimal: true,
            ..Default::default()
        };
