            assert!(dir.ends_with("staged-update"));
        }
    }

    #[test]
    fn staged_binary_path_has_correct_name() {
        if let Some(path) = staged_binary_path() {
            let name = path.file_name().unwrap().to_string_lossy();
            if cfg!(windows) {
                assert_eq!(name, "bivvy.exe");
            } else {
                assert_eq!(name, "bivvy");
            }
        }
    }

    #[test]
    fn check_staged_update_returns_none_when_no_staging() {
        // No staged update should exist in test environment
        // (unless a real update was staged, which is unlikely)
        // This primarily tests that the function doesn't panic
        let _ = check_staged_update();
    }

    #[test]
    fn clear_staged_update_is_idempotent() {
        // Should not error even when there's nothing to clear
        let result = clear_staged_update();
        assert!(result.is_ok());
    }

    #[test]
    fn should_spawn_returns_false_in_ci() {
        assert!(!should_spawn_background_update(true, true));
    }

    #[test]
    fn should_spawn_returns_false_when_non_interactive() {
        assert!(!should_spawn_background_update(false, false));
    }

    #[test]
    fn should_spawn_returns_true_in_interactive_non_ci() {
        // This may still return false if a lock file or staged update exists,
        // but the CI and interactive checks should pass
        let result = should_spawn_background_update(true, false);
        // Can't assert true because lock file state is unpredictable,
        // but we at least verify it doesn't panic
        let _ = result;
    }

    #[test]
    fn is_update_process_running_returns_false_without_lock() {
        // Without a lock file, should be false
        // (unless one exists from a real update, but unlikely in test)
        let _ = is_update_process_running();
    }

    #[test]
    fn write_and_check_lock_file() {
        // Write a lock file and verify it's detected
        if write_lock_file().is_ok() {
            assert!(is_update_process_running());
            remove_lock_file();
            // After removal, should no longer be running
            // (give a tiny margin for filesystem lag)
            assert!(!is_update_process_running());
        }
    }

    #[test]
    fn replace_binary_with_temp_files() {
        let temp = TempDir::new().unwrap();

        // Create a fake "current" binary
        let current = temp.path().join("bivvy");
        fs::write(&current, b"old version").unwrap();
        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt;
            let mut perms = fs::metadata(&current).unwrap().permissions();
            perms.set_mode(0o755);
            fs::set_permissions(&current, perms).unwrap();
        }

        // Create a fake "staged" binary
        let staged = temp.path().join("bivvy-staged");
        fs::write(&staged, b"new version").unwrap();

        // Replace
        let result = replace_binary(&staged, &current);
        assert!(result.is_ok(), "replace_binary failed: {:?}", result.err());

        // Verify content changed
        let content = fs::read_to_string(&current).unwrap();
        assert_eq!(content, "new version");

        // Verify temp file was cleaned up
        assert!(!temp.path().join("bivvy.new").exists());
    }

    #[test]
    fn apply_staged_update_returns_none_when_nothing_staged() {
        // In test environment, there should be no staged update
        let result = apply_staged_update().unwrap();
        assert!(result.is_none());
    }

    #[test]
    fn staged_metadata_path_returns_json_file() {
        if let Some(path) = staged_metadata_path() {
            assert_eq!(path.file_name().unwrap().to_string_lossy(), "metadata.json");
        }
    }

    #[test]
    fn lock_path_returns_lock_file() {
        if let Some(path) = lock_path() {
            assert_eq!(path.file_name().unwrap().to_string_lossy(), "update.lock");
        }
    }
}

//! Update command implementation.
//!
//! The `bivvy update` command checks for and installs updates.
//! It also provides flags to enable or disable automatic background updates.

use crate::error::Result;
use crate::ui::{OutputWriter, UserInterface};
use crate::updates::{
    auto_update::is_auto_update_enabled, check_for_updates_fresh, detect_install_method, VERSION,
};

use super::dispatcher::{Command, CommandResult};

/// Arguments for the `update` command.
#[derive(Debug, Clone, Default, clap::Args)]
pub struct UpdateArgs {
    /// Check for updates without installing
    #[arg(long)]
    pub check: bool,

    /// Enable automatic background updates
    #[arg(long, conflicts_with = "disable_auto_update")]
    pub enable_auto_update: bool,

    /// Disable automatic background updates
    #[arg(long, conflicts_with = "enable_auto_update")]
    pub disable_auto_update: bool,
}

/// The update command implementation.
pub struct UpdateCommand {
    args: UpdateArgs,
}

impl UpdateCommand {
    /// Create a new update command.
    pub fn new(args: UpdateArgs) -> Self {
        Self { args }
    }
}

impl Command for UpdateCommand {
    fn execute(&self, ui: &mut dyn UserInterface) -> Result<CommandResult> {
        // Handle auto-update toggle flags
        if self.args.enable_auto_update {
            return set_auto_update(ui, true);
        }
        if self.args.disable_auto_update {
            return set_auto_update(ui, false);
        }

        ui.message(&format!("Current version: {}", VERSION));

        // Show auto-update status
        if is_auto_update_enabled() {
            ui.message("Auto-update: enabled");
        } else {
            ui.message("Auto-update: disabled");
        }

        ui.message("Checking for updates...");

        let info = match check_for_updates_fresh() {
            Ok(info) => info,
            Err(e) => {
                ui.error(&format!("Failed to check for updates: {}", e));
                return Ok(CommandResult::failure(1));
            }
        };

        if !info.update_available {
            ui.message("You're on the latest version.");
            return Ok(CommandResult::success());
        }

        ui.message(&format!(
            "New version available: {} -> {}",
            info.current, info.latest
        ));

        if self.args.check {
            if let Some(url) = &info.release_url {
                ui.message(&format!("Release: {}", url));
            }
            return Ok(CommandResult::success());
        }

        let method = detect_install_method();

        if !method.supports_auto_update() {
            ui.message(&format!(
                "Auto-update is not supported for {} installs.",
                method.name()
            ));
            if let Some(url) = &info.release_url {
                ui.message(&format!("Download the latest version from: {}", url));
            }
            return Ok(CommandResult::success());
        }

        let update_cmd = method.update_command().unwrap();
        ui.message(&format!("Updating via: {}", update_cmd));

        let parts: Vec<&str> = update_cmd.split_whitespace().collect();
        let status = std::process::Command::new(parts[0])
            .args(&parts[1..])
            .status()?;

        if status.success() {
            ui.message("Update complete!");
            Ok(CommandResult::success())
        } else {
            ui.error("Update failed.");
            Ok(CommandResult::failure(1))
        }
    }
}

/// Write the auto_update setting to the system config at `~/.bivvy/config.yml`.
///
/// Only requires `OutputWriter` — displays confirmation messages but does not prompt.
fn set_auto_update(ui: &mut dyn OutputWriter, enabled: bool) -> Result<CommandResult> {
    let config_dir = crate::sys::bivvy_config_dir().ok_or_else(|| {
        crate::error::BivvyError::Other(anyhow::anyhow!("Could not determine config directory"))
    })?;

    let config_path = config_dir.join("config.yml");

    // Read existing config or start fresh
    let mut value: serde_yaml::Value = if config_path.exists() {
        let content = std::fs::read_to_string(&config_path).map_err(|e| {
            crate::error::BivvyError::Other(anyhow::anyhow!(
                "Failed to read {}: {}",
                config_path.display(),
                e
            ))
        })?;
        serde_yaml::from_str(&content)
            .unwrap_or(serde_yaml::Value::Mapping(serde_yaml::Mapping::new()))
    } else {
        serde_yaml::Value::Mapping(serde_yaml::Mapping::new())
    };

    // Ensure settings mapping exists
    let mapping = value.as_mapping_mut().ok_or_else(|| {
        crate::error::BivvyError::Other(anyhow::anyhow!("System config is not a YAML mapping"))
    })?;

    let settings_key = serde_yaml::Value::String("settings".to_string());
    if !mapping.contains_key(&settings_key) {
        mapping.insert(
            settings_key.clone(),
            serde_yaml::Value::Mapping(serde_yaml::Mapping::new()),
        );
    }

    let settings = mapping
        .get_mut(&settings_key)
        .and_then(|v| v.as_mapping_mut())
        .ok_or_else(|| {
            crate::error::BivvyError::Other(anyhow::anyhow!("settings is not a YAML mapping"))
        })?;

    settings.insert(
        serde_yaml::Value::String("auto_update".to_string()),
        serde_yaml::Value::Bool(enabled),
    );

    // Write back
    std::fs::create_dir_all(&config_dir)?;
    let yaml = serde_yaml::to_string(&value).map_err(|e| {
        crate::error::BivvyError::Other(anyhow::anyhow!("Failed to serialize config: {}", e))
    })?;
    std::fs::write(&config_path, yaml)?;

    if enabled {
        ui.message("Automatic background updates enabled.");
    } else {
        ui.message("Automatic background updates disabled.");
    }
    ui.message(&format!("Saved to {}", config_path.display()));

    Ok(CommandResult::success())
}

