        .unwrap();

        let config = load_merged_config(temp.path()).unwrap();
        let workflow = config.workflows.get("release").unwrap();
        assert_eq!(workflow.description, Some("Release".to_string()));
        assert_eq!(workflow.steps, vec!["fetch"]);
